import{z as r,x as s,o as e,c as d,q as i,j as o,D as t,d as E,s as B,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"constitutional 数据的生产","description":"","frontmatter":{"title":"constitutional 数据的生产","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-constitutional-data.md","filePath":"llm/ade-constitutional-data.md","lastUpdated":1791413859000}'),F={name:"llm/ade-constitutional-data.md"};function C(m,a,u,D,p,c){const l=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=i('<h1 id="constitutional-数据的生产" tabindex="-1">constitutional 数据的生产 <a class="header-anchor" href="#constitutional-数据的生产" aria-label="Permalink to &quot;constitutional 数据的生产&quot;">​</a></h1><div class="epigraph"><p>把原则写成文，让模型按原则批评、按批评改写——对齐数据的定义从标注员的内隐标准，换成一份可版本化的文本。</p><footer>—— 据 Bai 等 Constitutional AI, 2022 整理</footer></div><p><a href="/llm/ade-redteam-data">上一课</a>把红队发现沉淀成带政策版本的安全对子，判断的锚是人写的政策与指南。本课把锚整个换成一份成文原则：<a href="/llm/rlaif">RLAIF</a> 与 Constitutional AI 的数据生产线——用模型按原则批评与改写来生产 SFT 示范，用模型裁判按原则标注偏好对。主干已有 RLAIF 的框架位，本课写它的生产工程：一条产线怎么立、每一站的产物与门在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>人工标注有三重约束：贵且慢；一致率靠培训与仲裁维持；判断超出标注员专业的问题——高深领域的诚实性、专业域的危害边界——根本上不了产线。Constitutional AI 的答案是把定义外化成原则集，让模型照着执行；但这只是换了一种偏差来源，原则集怎么写、批评怎么落、改写怎么验收、裁判怎么标，每一处都会写进数据。粗糙生产线的失效形态：批评泛泛而谈、不引具体原则，改写无从下手；改写只软化措辞、不除危害，数据看着安全，评测一打就穿；裁判把自身偏好当原则的影子——长度、位置、自我偏好（<a href="/llm/llm-judge-bias">LLM 裁判偏差</a>列过的一样不少）随数据入库。<span class="marginnote">直觉类比：这像给一个能力很强的新员工发一本成文的行为手册，让他自查自纠，而不是每件事都等主管口头把关。手册写得越具体、越可引用（&quot;第 3 条：不得泄露个人隐私&quot;），员工自查就越有靶子；若只写&quot;要有职业操守&quot;这种空话，自查就会流于表面——原则集的写法直接决定整条产线的质量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产线五站。第一站原则集条目化：每条原则单列、可引用、可判决，按有用、诚实、无害分组，集合本身带版本——原则集就是这条产线的政策文件。第二站批评：提示模型对照具体原则条目评价自己的回答，输出结构化——引用原则号、指出违反处。第三站改写：按批评修订回答，修订后的示范进 SFT（论文里的 SL-CAI 路）。第四站 AI 裁判标注偏好：同一提示下多个回答按原则两两比较，配思维链判决，产出偏好对进 RM（RLAIF 路）。第五站人审锚定：抽样人工复核批评质量、改写效果与裁判-人一致率——方法就是<a href="/llm/annotation-agreement">标注一致性与仲裁</a>的那一套，只是对象从人工产线换成了机器产线。<span class="marginnote">两条去路里的缩写先说清：「SFT」就是拿示范问答做监督微调——修订后的回答当标准答案，教模型直接学会好行为；「RM」是奖励模型——从成对的&quot;哪个更好&quot;标注里学出一个打分器，供后续强化学习用。同一条产线出两种料：改写文本喂 SFT，偏好对喂 RM。</span></p>',7)),(e(),o(n,null,{default:t(()=>[B(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8E%9F%E5%88%99%E9%9B%86%EF%BC%9A%E6%9D%A1%E7%9B%AE%E5%8C%96%20%2B%20%E7%89%88%E6%9C%AC%22%5D%20--%3E%20C%5B%22%E6%89%B9%E8%AF%84%EF%BC%9A%E5%BC%95%E5%8E%9F%E5%88%99%E5%8F%B7%E6%8C%87%E5%87%BA%E8%BF%9D%E5%8F%8D%22%5D%0A%20%20C%20--%3E%20R%5B%22%E6%94%B9%E5%86%99%EF%BC%9A%E6%8C%89%E6%89%B9%E8%AF%84%E4%BF%AE%E8%AE%A2%22%5D%0A%20%20R%20--%3E%20SFT%5B%22%E4%BF%AE%E8%AE%A2%E7%A4%BA%E8%8C%83%E8%BF%9B%20SFT%22%5D%0A%20%20R%20--%3E%20JUDGE%5B%22AI%20%E8%A3%81%E5%88%A4%EF%BC%9A%E6%8C%89%E5%8E%9F%E5%88%99%E6%88%90%E5%AF%B9%E6%AF%94%E8%BE%83%22%5D%0A%20%20JUDGE%20--%3E%20PAIRS%5B%22%E5%81%8F%E5%A5%BD%E5%AF%B9%E8%BF%9B%20RM%22%5D%0A%20%20SFT%20--%3E%20ANCH%5B%22%E4%BA%BA%E5%AE%A1%E9%94%9A%E5%AE%9A%EF%BC%9A%E6%8A%BD%E6%A0%B7%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20PAIRS%20--%3E%20ANCH%0A%20%20ANCH%20--%3E%7C%22%E4%B8%80%E8%87%B4%E7%8E%87%E6%8E%89%E5%87%BA%E9%97%A8%E7%A6%81%22%7C%20P%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("这条产线在机制上为什么成立：批评-改写把「这条回答不好」的二值判断分解成「定位违反加定点修改」两步，每一步都更接近可验证的文本操作；偏好标注同理，原则给了裁判一个显式锚，代替「我觉得哪个好」的内隐标准。产量因此从「按条人天」变成「按条推理」，分布可以直接由原则集编程——改一条原则、重跑批评与标注，数据分布跟着动，迭代速度是人标没有的。但机制的红线也在这：裁判模型把自己的偏好当原则的影子写进数据（"),A("a",{href:"/llm/self-preference-bias"},"自我偏好"),E("），修订可能只在长度、格式这些表面特征上服从原则——所以人审锚定不是装饰，是产线的质检门；批评与改写的质量抽检，盯的正是「服从发生在哪一层」。")],-1)),(e(),o(n,null,{default:t(()=>[B(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20CR%5B%22%E6%89%B9%E8%AF%84%EF%BC%9A%E5%BC%95%E5%8E%9F%E5%88%99%E5%8F%B7%E5%AE%9A%E4%BD%8D%E8%BF%9D%E5%8F%8D%22%5D%20--%3E%20SURF%5B%22%E8%A1%A8%E9%9D%A2%E6%9C%8D%E4%BB%8E%EF%BC%9A%E5%8F%AA%E8%BD%AF%E5%8C%96%E6%8E%AA%E8%BE%9E%22%5D%0A%20%20CR%20--%3E%20SUB%5B%22%E5%AE%9E%E8%B4%A8%E4%BF%AE%E8%AE%A2%EF%BC%9A%E9%99%A4%E5%8E%BB%E5%8D%B1%E5%AE%B3%E5%86%85%E5%AE%B9%22%5D%0A%20%20SURF%20--%3E%20BAD%5B%22%E7%9C%8B%E7%9D%80%E5%AE%89%E5%85%A8%EF%BC%8C%E8%AF%84%E6%B5%8B%E4%B8%80%E6%89%93%E5%B0%B1%E7%A9%BF%22%5D%0A%20%20SUB%20--%3E%20GOOD%5B%22%E7%A4%BA%E8%8C%83%E7%9C%9F%E6%AD%A3%E5%8F%AF%E7%94%A8%EF%BC%8C%E8%BF%9B%20SFT%22%5D%0A%20%20CHK%5B%22%E4%BA%BA%E5%AE%A1%E6%8A%BD%E6%A3%80%EF%BC%9A%E6%9C%8D%E4%BB%8E%E5%8F%91%E7%94%9F%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%22%5D%20--%3E%20SURF%0A%20%20CHK%20--%3E%20SUB%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">Bai et al. 2022 报告 AI 标注在 RM 验证集上的偏好判断与人工标注相当。注意那是一个静态验证集：裁判与人在新分布、新攻击上的一致率要另测，「验证集相当」读不成「处处相当」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>原则集有立场负载，版本即政策；改版要走数据卡的账（第一课的资产观在这里兑现）。constitutional 数据不替代安全评测：产线自我声明安全，评测要独立打，两套账不能混。闭环还有自我收缩的风险：裁判与生成器同源时，分布会向裁判的支撑收，<a href="/llm/self-rewarding-lm">自奖励语言模型</a>把这条推到极端。判断超出成文原则的问题，站在<a href="/llm/scalable-oversight">可扩展监督</a>的地界，本课程不展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原则集条目化并带版本，把「好」的定义从内隐标准外化成文本；批评、改写、裁判三步把它执行成数据。</li><li>修订示范进 SFT，成对比较的 AI 标注进 RM；人审锚定是产线质检门，不是装饰。</li><li>裁判偏差随数据入库：自我偏好、长度、位置一样不少，裁判-人一致率必须独立测。</li><li>分布可由原则集编程——迭代快，但改版要走数据卡的账。</li><li>出处：Bai 等 Constitutional AI，2022；裁判偏差与一致性口径见本课程相应各课。</li></ul>',5))])}const S=r(F,[["render",C]]);export{f as __pageData,S as default};
